def kernel(a, b):
    M, K = a.shape
    K2, N = b.shape
    assert K == K2, "Inconsistent dimensions for matrix multiplication"
    result = np.zeros((M, N), dtype=np.float32)
    tile_size_a = 128
    tile_size_b = 512

    for i in range(0, M, tile_size_a):
        for j in range(0, N, tile_size_b):
            for ii in range(i, min(i + tile_size_a, M)):
                for jj in range(j, min(j + tile_size_b, N)):
                    val = 0.0
                    for k in range(K):
                        val += a[ii, k] * b[k, jj]
                    result[ii, jj] = val
    return result

